CATEGORIES = [
    {"id": "addressing", "title": "Addressing & Subnets", "color": "sky", "blurb": "IPv4, IPv6, CIDR prefixes, masks and subnet planning."},
    {"id": "protocols", "title": "Protocols", "color": "mint", "blurb": "DNS, TCP, UDP, HTTP, TLS and the packets between them."},
    {"id": "routing", "title": "Routing & Boundaries", "color": "lilac", "blurb": "Routes, gateways, NAT, firewalls and segmentation."},
    {"id": "cloud", "title": "Cloud & Kubernetes Networks", "color": "peach", "blurb": "VPCs, endpoints, load balancers and pod networking."},
    {"id": "operations", "title": "Troubleshooting", "color": "rose", "blurb": "Trace a packet path and isolate DNS, MTU and reachability failures."},
]

def _lesson(id, title, category, level, what, example, key, question, answer, related=()):
    return topic(
        id, title, category, level, "NET", title + " in a packet path",
        "Think of a network as a postal system: addresses identify destinations, prefixes define neighborhoods, and routers choose the next street.",
        what, ["Designing and debugging real application paths.", "Explaining the packet-level reason a connection succeeds or fails."],
        [key, "Change one layer at a time and verify the result from the source and destination."],
        [ex("Try it", level, "A small command or calculation to make the idea concrete.", "text", example, runnable=False)],
        [example, "ip route get 10.20.3.14", "dig +trace example.com", "curl -v https://example.com"],
        ["A correct route does not guarantee that a firewall, return route, DNS answer or application listener is correct."],
        [qa(level, question, answer)], list(related),
        chain(("Source", "address + port", "Build the packet", "The source creates a packet for a destination address and service."),
              ("Network", "prefix + route", "Choose a path", key),
              ("Destination", "listener + response", "Verify both ways", "A working connection needs a return path and an accepting service.")),
    )

TOPICS = [
    _lesson("ip-addressing", "IPv4 Addresses & Network Bits", "addressing", "basic", "An IPv4 address is 32 bits written as four decimal octets. A prefix says how many leading bits identify the network; the remaining bits identify addresses inside that network.", "192.168.10.25/24", "IPv4 has 32 total bits; /24 leaves 8 host bits and 256 total addresses.", "What does /24 mean in 192.168.10.25/24?", "The first 24 bits are the network portion. The last 8 bits vary within that subnet, giving 2^8 = 256 addresses (usually 254 assignable hosts on a conventional subnet).", ["cidr-prefixes", "subnet-masks"]),
    _lesson("cidr-prefixes", "CIDR Prefixes: /24, /32 & /64", "addressing", "basic", "CIDR writes a prefix length after an address. For IPv4, /24 is a common 256-address subnet and /32 identifies exactly one address. IPv6 has 128 bits; /64 is the common subnet size and /128 is one address.", "IPv4: 10.2.4.0/24 · host route: 10.2.4.9/32 · IPv6 LAN: 2001:db8:1::/64", "The number after the slash counts network bits, not hosts. Remaining bits = address width − prefix.", "How many addresses are in an IPv4 /24 and an IPv6 /64?", "IPv4 /24 has 2^8 = 256 total addresses. IPv6 /64 has 2^64 addresses. Do not treat IPv6 /64 like an IPv4 /24: the address widths differ.", ["ipv6", "subnet-masks"]),
    _lesson("subnet-masks", "Subnet Masks & Binary AND", "addressing", "intermediate", "A subnet mask is the dotted-decimal form of a prefix. Bitwise AND between an address and its mask produces the network address. A /24 mask is 255.255.255.0; a /20 mask is 255.255.240.0.", "192.168.18.77 AND 255.255.240.0 = 192.168.16.0", "Masks contain contiguous 1 bits followed by 0 bits; non-contiguous masks are not valid CIDR prefixes.", "What network contains 192.168.18.77/20?", "The /20 mask is 255.255.240.0. The third octet is grouped in blocks of 16, so 18 belongs to the 16–31 block: network 192.168.16.0/20.", ["cidr-prefixes"]),
    _lesson("subnetting-vlsm", "Subnetting & VLSM", "addressing", "intermediate", "Subnetting divides an address block into smaller prefixes. Variable Length Subnet Masking (VLSM) assigns different-sized blocks to teams based on need. A /24 can be split into four /26 blocks, each with 64 addresses.", "10.0.0.0/24 → 10.0.0.0/26, .64/26, .128/26, .192/26", "Splitting a prefix by k bits creates 2^k equal subnets; each child has 2^k fewer host bits.", "How many /26 subnets fit in a /24?", "Two extra network bits create 2^2 = 4 subnets. Each /26 contains 64 IPv4 addresses (62 conventional usable hosts).", ["cidr-prefixes", "private-addresses"]),
    _lesson("ipv6", "IPv6 Addressing & Prefixes", "addressing", "intermediate", "IPv6 uses 128-bit addresses written in hexadecimal groups. Zero compression with :: can appear once per address. A /64 is the normal subnet for a LAN; /128 names one exact address, and IPv6 has no broadcast address.", "2001:db8:1234:1::25/64", "A /64 leaves 64 interface bits. IPv6 uses multicast and neighbor discovery instead of broadcast and ARP.", "Why is /64 common for an IPv6 subnet?", "It leaves 64 interface identifier bits and aligns with standard IPv6 autoconfiguration and neighbor discovery assumptions. A /128 is a single route/host address.", ["cidr-prefixes", "neighbor-discovery"]),
    _lesson("private-addresses", "Private, Public & Link-Local Ranges", "addressing", "basic", "Private IPv4 ranges are 10/8, 172.16/12 and 192.168/16. They are not globally routed. 169.254/16 is IPv4 link-local; IPv6 uses unique-local fc00::/7 and link-local fe80::/10.", "ip route get 8.8.8.8", "Private addresses need NAT or a private interconnect to reach public networks; overlapping private ranges complicate peering.", "Can two VPCs with the same 10.0.0.0/16 range be directly peered?", "Usually not: overlapping CIDRs make destination selection ambiguous. Renumber one side, use translation, or route through an architecture that explicitly handles the overlap.", ["vpc-design", "nat"]),
    _lesson("dns-resolution", "DNS Resolution & Record Types", "protocols", "basic", "DNS maps names to records through recursive resolvers and authoritative servers. A, AAAA, CNAME, MX, TXT, NS and PTR records serve different purposes; TTL controls how long answers may be cached.", "dig A api.example.com +trace", "DNS can fail before a packet reaches the service; compare resolver answers, authoritative records and cached TTLs.", "Why can a DNS change take time to appear?", "Resolvers and clients cache answers until TTL expiry. Negative answers can also be cached, so verify the record at authoritative and recursive resolvers.", ["tls-handshake", "route-tables"]),
    _lesson("tcp-udp", "TCP, UDP & Ports", "protocols", "basic", "TCP provides an ordered reliable byte stream with connection setup, retransmission and flow control. UDP sends datagrams without connection guarantees. Ports identify services on a host; a listening socket needs both a reachable address and an allowed path.", "ss -lntup", "A successful TCP handshake proves the port accepted a connection; it does not prove the application request will succeed.", "When might UDP be preferable to TCP?", "When low-latency datagrams or application-controlled reliability matter, such as DNS, voice/video and QUIC. UDP itself does not guarantee delivery or ordering.", ["http-tls", "firewalls"]),
    _lesson("http-tls", "HTTP, TLS & Connection Setup", "protocols", "intermediate", "HTTPS layers HTTP over TLS, which authenticates the server and protects traffic in transit. Name resolution, routing, TCP (or QUIC), TLS and HTTP happen in sequence; a failure at each layer looks different.", "curl -v https://example.com", "Certificate name, trust chain, expiry, SNI and system clock can all break TLS even when TCP connects.", "How do you separate a TLS problem from a routing problem?", "First verify DNS and TCP reachability, then inspect the TLS handshake and certificate. A timeout before connect suggests a path issue; a certificate alert after connect points to TLS configuration or trust.", ["dns-resolution", "tcp-udp"]),
    _lesson("route-tables", "Routing Tables & Longest Prefix Match", "routing", "intermediate", "Routers select the most specific matching route (longest prefix match), then forward to a next hop or interface. A default route is used only when no more-specific route matches.", "ip route get 10.20.3.14", "More-specific prefixes win: 10.20.0.0/16 is selected over 10.0.0.0/8 for 10.20.3.14.", "A host has a /16 route and a /24 route for the same destination. Which wins?", "The /24 route wins because it matches more leading bits and is more specific. Route metrics decide among otherwise equivalent routes.", ["vpc-design", "packet-tracing"]),
    _lesson("nat", "NAT, SNAT & DNAT", "routing", "intermediate", "Network Address Translation rewrites packet addresses. SNAT commonly lets private hosts share an outbound public address; DNAT or a load balancer maps inbound traffic to private services. NAT does not automatically make a private host reachable from the internet.", "Private host → SNAT/NAT gateway → public destination", "A stateful NAT device tracks flows so return packets map back to the original private host.", "Why does a private subnet need a route to a NAT gateway?", "The route sends internet-bound traffic through the NAT device, which also needs its own public route. Without both route legs, return traffic cannot complete.", ["private-addresses", "route-tables"]),
    _lesson("firewalls", "Firewalls, Security Groups & ACLs", "routing", "intermediate", "Firewalls filter traffic by addresses, ports, protocol and connection state. Stateful rules track return traffic; stateless ACLs require explicit inbound and outbound rules. A deny can come from any layer in the path.", "Allow TCP 443 from 10.0.0.0/16; deny other inbound traffic", "Debug source egress, destination ingress and return traffic independently; check the narrowest relevant rule first.", "Why might an inbound allow still not permit a connection?", "The source may lack egress, a stateless ACL may block the return path, a route may be missing, or the application may not be listening.", ["security-groups-nacls", "packet-tracing"]),
    _lesson("vpc-design", "VPC & Subnet Design", "cloud", "intermediate", "A VPC is a logically isolated IP space with subnets, route tables and gateways. Reserve non-overlapping CIDRs, place public ingress separately from private application and data tiers, and size blocks for growth.", "VPC 10.20.0.0/16 → public /24 + app /20 + data /24 per AZ", "Subnet routes, not the subnet name, determine whether a subnet is public. Public reachability also needs a public address and security policy.", "What makes a subnet public?", "A route to an internet gateway makes it internet-routable, but a host also needs a public address and permissive security rules for inbound access.", ["cidr-prefixes", "route-tables", "nat"]),
    _lesson("vpc-peering-tgw", "VPC Peering & Transit Gateways", "cloud", "intermediate", "Peering connects two VPCs directly but is non-transitive. A transit gateway provides a hub for many VPCs and on-prem networks. Both sides need routes and non-overlapping address spaces.", "VPC A → Transit Gateway → VPC B", "Peering is simple for a few networks; a transit gateway centralizes routing at larger scale and must be designed to avoid unintended reachability.", "Can VPC A reach VPC C through a peering between A–B and B–C?", "No. VPC peering is not transitive. Add direct peering or route through a transit gateway/appliance designed for transit.", ["vpc-design", "route-tables"]),
    _lesson("load-balancing", "Load Balancers & Health Checks", "cloud", "intermediate", "A load balancer distributes connections or requests among targets and removes unhealthy targets from rotation. Layer 4 balances transport flows; Layer 7 can route using HTTP host, path and headers.", "Client → HTTPS listener → healthy app targets", "Health checks should test meaningful readiness without requiring every optional dependency to be available.", "Why can a target pass a TCP health check but still return 500 errors?", "A TCP check confirms only that a port accepts connections. Add an application-level health check and inspect dependencies, target registration and request routing.", ["http-tls", "vpc-design"]),
    _lesson("kubernetes-networking", "Kubernetes Service & Pod Networking", "cloud", "intermediate", "Kubernetes networking gives pods routable IPs, Services stable virtual addresses, and kube-proxy or eBPF datapaths service forwarding. CNI plugins allocate pod addresses and connect nodes.", "kubectl get pods,svc,endpoints -o wide", "A Service with no endpoints points to selector/readiness problems; a pod-to-pod failure can be a CNI route or NetworkPolicy issue.", "A Service resolves but has no backends. What do you inspect?", "Check the Service selector, pod labels, readiness, EndpointSlices and namespace. Then inspect policies and the CNI path if endpoints exist but traffic fails.", ["firewalls", "packet-tracing"]),
    _lesson("packet-tracing", "Packet-Path Troubleshooting", "operations", "intermediate", "Trace a flow hop by hop: resolve the name, identify the source IP and route, check egress and ingress policy, confirm listener and return route, then inspect application logs. Capture timestamps and the 5-tuple.", "dig api.example.com; traceroute api.example.com; nc -vz api.example.com 443", "A packet trace becomes actionable when it records source, destination, protocol, ports, time, route and the first point where expected traffic disappears.", "A client times out connecting to a service. What is your first diagnostic sequence?", "Resolve the name, test the destination IP and port, inspect the source route and egress rules, destination ingress rules, return routes, and listener. Compare flow logs at each boundary.", ["dns-resolution", "route-tables", "firewalls"]),
    _lesson("mtu-fragmentation", "MTU, MSS & Path MTU Discovery", "operations", "advanced", "MTU limits the packet size a link can carry. Tunnels add headers and reduce effective MTU. If ICMP needed for Path MTU Discovery is blocked, small requests may work while large responses stall.", "ping -D -s 1472 -M do destination", "Symptoms that appear only for large payloads often indicate an MTU/MSS problem rather than DNS or application logic.", "Why can a TLS connection hang only when large responses are sent?", "A path MTU black hole can drop oversized packets while small handshake packets pass. Check tunnel MTUs, MSS clamping and ICMP filtering end to end.", ["http-tls", "packet-tracing"]),
]

